fn check(ok:bool){if !ok{let _=fail(0);}}fn fail(x:u8)->u8{1/x}
use core::cmp::Ordering;fn rank(x:Option<Ordering>)->i8{match x{None=>2,Some(Ordering::Less)=>-1,Some(Ordering::Equal)=>0,Some(Ordering::Greater)=>1}}
fn main(){let a=[1u8,9];let b=[2u8,0];check(a<b);check(a<=b);check(!(a>b));check(!(a>=b));check(rank(a.partial_cmp(&b))==-1);check(a.cmp(&a)==Ordering::Equal);check(a.cmp(&b)==Ordering::Less);}